class Solution {
    int solve(int n) {
        if (n < 3) return 0;
        boolean[] c = new boolean[n];
        int cnt = 0;
        for (int i = 2; i < n; i++) {
            if (!c[i]) { cnt++; for (long j = (long)i * i; j < n; j += i) c[(int)j] = true; }
        }
        return cnt;
    }
}

