import java.util.*;
class TreeNode { int val; TreeNode left, right; TreeNode(int v){ val = v; } }
class TreeUtil {
    static TreeNode build(String[] a) {
        if (a.length == 0 || a[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(a[0]));
        ArrayDeque<TreeNode> q = new ArrayDeque<>(); q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < a.length) {
            TreeNode n = q.poll();
            if (i < a.length && !a[i].equals("null")) { n.left = new TreeNode(Integer.parseInt(a[i])); q.add(n.left); } i++;
            if (i < a.length && !a[i].equals("null")) { n.right = new TreeNode(Integer.parseInt(a[i])); q.add(n.right); } i++;
        }
        return root;
    }
    static String[] ser(TreeNode root) {
        List<String> out = new ArrayList<>();
        if (root == null) return new String[0];
        LinkedList<TreeNode> q = new LinkedList<>(); q.add(root);
        while (!q.isEmpty()) {
            TreeNode n = q.poll();
            if (n == null) { out.add("null"); continue; }
            out.add(String.valueOf(n.val)); q.add(n.left); q.add(n.right);
        }
        while (!out.isEmpty() && out.get(out.size()-1).equals("null")) out.remove(out.size()-1);
        return out.toArray(new String[0]);
    }
}
class Solution {
    int solve(String[] level) {
        return depth(TreeUtil.build(level));
    }
    int depth(TreeNode n) { return n == null ? 0 : 1 + Math.max(depth(n.left), depth(n.right)); }
}

