from collections import deque
class TreeNode:
    def __init__(self, v): self.val = v; self.left = None; self.right = None
def build_tree(a):
    if not a or a[0] == 'null': return None
    root = TreeNode(int(a[0])); q = deque([root]); i = 1
    while q and i < len(a):
        n = q.popleft()
        if i < len(a) and a[i] != 'null': n.left = TreeNode(int(a[i])); q.append(n.left)
        i += 1
        if i < len(a) and a[i] != 'null': n.right = TreeNode(int(a[i])); q.append(n.right)
        i += 1
    return root
def ser_tree(root):
    if not root: return []
    out = []; q = deque([root])
    while q:
        n = q.popleft()
        if n is None: out.append('null'); continue
        out.append(str(n.val)); q.append(n.left); q.append(n.right)
    while out and out[-1] == 'null': out.pop()
    return out
def solve(level):
    def d(n):
        return 0 if n is None else 1 + max(d(n.left), d(n.right))
    return d(build_tree(level))

