class ListNode { int val; ListNode next; ListNode(int v){ val = v; } }
class ListUtil {
    static ListNode build(int[] a){ ListNode dummy=new ListNode(0), t=dummy; for(int x:a){ t.next=new ListNode(x); t=t.next; } return dummy.next; }
    static int[] ser(ListNode h){ List<Integer> o=new ArrayList<>(); while(h!=null){ o.add(h.val); h=h.next; } int[] r=new int[o.size()]; for(int i=0;i<r.length;i++) r[i]=o.get(i); return r; }
    static ListNode buildCycle(int[] a, int pos){ ListNode dummy=new ListNode(0), t=dummy, cyc=null; int idx=0; for(int x:a){ t.next=new ListNode(x); t=t.next; if(idx==pos) cyc=t; idx++; } if(pos>=0) t.next=cyc; return dummy.next; }
    static int indexOf(ListNode h, ListNode target){ int i=0; while(h!=null){ if(h==target) return i; h=h.next; i++; } return -1; }
}
class Solution {
    int[] solve(int[] a, int[] b){ ListNode x=ListUtil.build(a), y=ListUtil.build(b), dummy=new ListNode(0), t=dummy; int carry=0; while(x!=null||y!=null||carry>0){ int s=carry; if(x!=null){ s+=x.val; x=x.next; } if(y!=null){ s+=y.val; y=y.next; } t.next=new ListNode(s%10); t=t.next; carry=s/10; } return ListUtil.ser(dummy.next); }
}

