def solve(grid, word):
    g=[list(r) for r in grid]; R=len(g); C=len(g[0]) if R else 0
    def dfs(r,c,i,seen):
        if i==len(word): return True
        if r<0 or r>=R or c<0 or c>=C or (r,c) in seen or g[r][c]!=word[i]: return False
        seen.add((r,c))
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            if dfs(r+dr,c+dc,i+1,seen): seen.discard((r,c)); return True
        seen.discard((r,c)); return False
    for r in range(R):
        for c in range(C):
            if dfs(r,c,0,set()): return True
    return False

