        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        int q=Integer.parseInt(br.readLine().trim());
        Deque<int[]> st=new ArrayDeque<>(); StringBuilder sb=new StringBuilder();
        for(int i=0;i<q;i++){ StringTokenizer t=new StringTokenizer(br.readLine()); String op=t.nextToken();
            if(op.equals("push")){ int x=Integer.parseInt(t.nextToken()); int mn=st.isEmpty()?x:Math.min(st.peek()[1],x); st.push(new int[]{x,mn}); }
            else if(op.equals("pop")) st.pop();
            else if(op.equals("top")) sb.append(st.peek()[0]).append('\n');
            else if(op.equals("getMin")) sb.append(st.peek()[1]).append('\n'); }
        System.out.print(sb);
    }
}

