        elif op=='put':
            k,v=int(p[1]),int(p[2])
            if k in od: od.move_to_end(k)
            od[k]=v
            if len(od)>cap: od.popitem(last=False)
        elif op=='get':
            k=int(p[1])
            if k in od: od.move_to_end(k); out.append(str(od[k]))
            else: out.append('-1')
