    int solve(int n, int[] u, int[] v, int[] w, int src){ List<int[]>[] adj=new List[n]; for(int i=0;i<n;i++) adj[i]=new ArrayList<>(); for(int i=0;i<u.length;i++) adj[u[i]].add(new int[]{v[i],w[i]}); long[] dist=new long[n]; Arrays.fill(dist,Long.MAX_VALUE); dist[src]=0; PriorityQueue<long[]> pq=new PriorityQueue<>((a,b)->Long.compare(a[0],b[0])); pq.offer(new long[]{0,src}); while(!pq.isEmpty()){ long[] c=pq.poll(); long d=c[0]; int x=(int)c[1]; if(d>dist[x]) continue; for(int[] e:adj[x]) if(d+e[1]<dist[e[0]]){ dist[e[0]]=d+e[1]; pq.offer(new long[]{dist[e[0]],e[0]}); } } long m=0; for(long dd:dist){ if(dd==Long.MAX_VALUE) return -1; m=Math.max(m,dd); } return (int)m; }
