import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt(), W = sc.nextInt();
        char[][] g = new char[H][];
        for (int i = 0; i < H; i++) g[i] = sc.next().toCharArray();
        int[][] dist = new int[H][W];
        for (int[] row : dist) Arrays.fill(row, -1);
        int si = 0, sj = 0, gi = 0, gj = 0;
        for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) {
            if (g[i][j] == 'S') { si = i; sj = j; }
            else if (g[i][j] == 'G') { gi = i; gj = j; }
        }
        int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};
        dist[si][sj] = 0;
        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{si, sj});
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int d = 0; d < 4; d++) {
                int ni = cur[0] + dr[d], nj = cur[1] + dc[d];
                if (ni < 0 || ni >= H || nj < 0 || nj >= W) continue;
                if (g[ni][nj] == '#' || dist[ni][nj] >= 0) continue;
                dist[ni][nj] = dist[cur[0]][cur[1]] + 1;
                q.add(new int[]{ni, nj});
            }
        }
        System.out.println(dist[gi][gj]);
    }
}

