        int H = sc.nextInt(), W = sc.nextInt();
        char[][] g = new char[H][];
        for (int i = 0; i < H; i++) g[i] = sc.next().toCharArray();
        Deque<int[]> q = new ArrayDeque<>();
        int fresh = 0;
        for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) {
            if (g[i][j] == 'R') q.add(new int[]{i, j, 0});
            else if (g[i][j] == 'F') fresh++;
        }
        int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};
        int last = 0;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            last = Math.max(last, cur[2]);
            for (int d = 0; d < 4; d++) {
                int ni = cur[0] + dr[d], nj = cur[1] + dc[d];
                if (ni < 0 || ni >= H || nj < 0 || nj >= W) continue;
                if (g[ni][nj] != 'F') continue;
                g[ni][nj] = 'R';
                fresh--;
                q.add(new int[]{ni, nj, cur[2] + 1});
            }
        }
        System.out.println(fresh > 0 ? -1 : last);
    }
}

