        Arrays.sort(it, (p, q) -> {
            long l = p[0] * q[1], r = q[0] * p[1];
            if (l != r) return Long.compare(r, l);
            return Long.compare(p[1], q[1]);
        });
        long total = 0, left = C;
        for (long[] item : it) {
            if (left == 0) break;
            long take = Math.min(item[1], left);
            total += item[0] * 100 * take / item[1];
            left -= take;
        }
        System.out.println(total);
    }
}

