        int[] coins = new int[n];
        for (int i = 0; i < n; i++) coins[i] = sc.nextInt();
        Arrays.sort(coins);
        int left = amount, greedy = 0;
        for (int i = n - 1; i >= 0; i--) { greedy += left / coins[i]; left %= coins[i]; }
        if (left != 0) greedy = -1;
        final int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int a = 1; a <= amount; a++)
            for (int c : coins)
                if (c <= a && dp[a - c] + 1 < dp[a]) dp[a] = dp[a - c] + 1;
        int best = dp[amount] >= INF ? -1 : dp[amount];
        System.out.println(greedy + " " + best);
    }
}

