        for (int i = 0; i < n; i++) {
            if (i > 0 && a[i] == a[i - 1]) continue;
            int l = i + 1, r = n - 1;
            while (l < r) {
                long s = (long) a[i] + a[l] + a[r];
                if (s < 0) l++;
                else if (s > 0) r--;
                else {
                    count++;
                    l++; r--;
                    while (l < r && a[l] == a[l - 1]) l++;
                }
            }
        }
        return count;
    }

