public class Main {
    static long solve(int[] a, long k) {
        int n = a.length;
        long[] dp = new long[n];
        int[] dq = new int[n];
        int head = 0, tail = 0;
        dp[0] = a[0];
        dq[tail++] = 0;
        for (int i = 1; i < n; i++) {
            while (dq[head] < i - k) head++;
            dp[i] = a[i] + dp[dq[head]];
            while (tail > head && dp[dq[tail - 1]] <= dp[i]) tail--;
            dq[tail++] = i;
        }
        return dp[n - 1];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
