    static int solve(int[] h, long bricks, long ladders) {
        PriorityQueue<Integer> climbs = new PriorityQueue<>();
        for (int i = 0; i + 1 < h.length; i++) {
            int d = h[i + 1] - h[i];
            if (d <= 0) continue;
            climbs.offer(d);
            if (climbs.size() > ladders) {
                bricks -= climbs.poll();
                if (bricks < 0) return i;
            }
        }
        return h.length - 1;
    }

