import java.util.*;

public class Main {
    static long solve(int[][] m) {
        int r = m.length, c = m[0].length;
        boolean[][] seen = new boolean[r][c];
        PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++)
                if (i == 0 || j == 0 || i == r - 1 || j == c - 1) { pq.offer(new int[]{m[i][j], i, j}); seen[i][j] = true; }
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        long water = 0;
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            for (int[] d : dirs) {
                int ni = cur[1] + d[0], nj = cur[2] + d[1];
                if (ni < 0 || nj < 0 || ni >= r || nj >= c || seen[ni][nj]) continue;
                seen[ni][nj] = true;
                water += Math.max(0, cur[0] - m[ni][nj]);
                pq.offer(new int[]{Math.max(cur[0], m[ni][nj]), ni, nj});
            }
        }
        return water;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        int[][] m = new int[r][c];
        for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) m[i][j] = sc.nextInt();
        System.out.println(solve(m));
    }
}

