import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

L = sys.stdin.read().split('\n')
q = int(L[0])
ops = [L[1 + i].split() for i in range(q)]

def solve(ops):
    price_at = {}
    latest = 0
    hi, lo = [], []
    out = []
    for op in ops:
        if op[0] == "update":
            t, p = int(op[1]), int(op[2])
            price_at[t] = p
            latest = max(latest, t)
            heapq.heappush(hi, (-p, t))
            heapq.heappush(lo, (p, t))
        elif op[0] == "current":
            out.append(str(price_at[latest]))
        elif op[0] == "maximum":
            while price_at[hi[0][1]] != -hi[0][0]:
                heapq.heappop(hi)
            out.append(str(-hi[0][0]))
        else:
            while price_at[lo[0][1]] != lo[0][0]:
                heapq.heappop(lo)
            out.append(str(lo[0][0]))
    return "\n".join(out)

print(solve(ops))

