import java.util.*;

public class Main {
    static int solve(String target, String[] deadends) {
        Set<String> seen = new HashSet<>(Arrays.asList(deadends));
        if (seen.contains("0000")) return -1;
        seen.add("0000");
        ArrayDeque<String> q = new ArrayDeque<>();
        q.add("0000");
        for (int steps = 0; !q.isEmpty(); steps++) {
            for (int k = q.size(); k > 0; k--) {
                String cur = q.poll();
                if (cur.equals(target)) return steps;
                char[] ch = cur.toCharArray();
                for (int i = 0; i < 4; i++) {
                    char orig = ch[i];
                    int d = orig - '0';
                    for (int nd : new int[]{(d + 1) % 10, (d + 9) % 10}) {
                        ch[i] = (char) ('0' + nd);
                        String next = new String(ch);
                        if (seen.add(next)) q.add(next);
                    }
                    ch[i] = orig;
                }
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int k = sc.nextInt();
        String[] words = new String[k];
        for (int i = 0; i < k; i++) words[i] = sc.next();
        System.out.println(solve(s, words));
    }
}

