            if (cur[1] == n - 1 && cur[2] == n - 1) return cur[0];
            for (int[] d : dirs) {
                int x = cur[1] + d[0], y = cur[2] + d[1];
                if (x < 0 || y < 0 || x >= n || y >= n || seen[x][y]) continue;
                seen[x][y] = true;
                pq.add(new int[]{Math.max(cur[0], m[x][y]), x, y});
