public class Main {
    static int solve(int[][] clips, int T) {
        int[] reach = new int[T + 1];
        for (int[] c : clips) if (c[0] <= T) reach[c[0]] = Math.max(reach[c[0]], c[1]);
        int used = 0, covered = 0, furthest = 0;
        for (int t = 0; t < T; t++) {
            furthest = Math.max(furthest, reach[t]);
            if (t == covered) {
                if (furthest <= t) return -1;
                used++;
                covered = furthest;
            }
        }
        return used;
    }

