    static long rob(int[] a, int lo, int hi) {
        long prev = 0, cur = 0;
        for (int i = lo; i <= hi; i++) {
            long next = Math.max(cur, prev + a[i]);
            prev = cur;
            cur = next;
        }
        return cur;
