import java.util.*;

public class Main {
    static long solve(int[][] g) {
        int r = g.length, c = g[0].length;
        long[] dp = new long[c];
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                if (i == 0 && j == 0) dp[j] = g[0][0];
                else if (i == 0) dp[j] = dp[j - 1] + g[i][j];
                else if (j == 0) dp[j] = dp[j] + g[i][j];
                else dp[j] = Math.min(dp[j], dp[j - 1]) + g[i][j];
            }
        return dp[c - 1];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        int[][] m = new int[r][c];
        for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) m[i][j] = sc.nextInt();
        System.out.println(solve(m));
    }
}

