        int n = s.length(), m = t.length();
        long[] ways = new long[m + 1];
        ways[0] = 1;
        for (int i = 0; i < n; i++)
            for (int j = m; j >= 1; j--)
                if (s.charAt(i) == t.charAt(j - 1)) ways[j] = (ways[j] + ways[j - 1]) % MOD;
        return ways[m];
    }

