import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next

def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head

def dump(head):
