head = build([int(x) for x in d[1:1 + n]])

def solve(head):
    def merge(a, b):
        dummy = tail = ListNode(0)
        while a and b:
            if a.val <= b.val:
                tail.next, a = a, a.next
            else:
                tail.next, b = b, b.next
            tail = tail.next
        tail.next = a or b
        return dummy.next

    def sort(h):
        if not h or not h.next:
            return h
        slow, fast = h, h.next
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
        right = slow.next
        slow.next = None
        return merge(sort(h), sort(right))

    return sort(head)

