import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    static TreeNode build(String line) {
        String t = line.trim();
        if (t.isEmpty()) return null;
        String[] a = t.split("\\s+");
        if (a[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(a[0]));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < a.length) {
            TreeNode node = q.poll();
            if (i < a.length && !a[i].equals("null")) { node.left = new TreeNode(Integer.parseInt(a[i])); q.add(node.left); }
            i++;
            if (i < a.length && !a[i].equals("null")) { node.right = new TreeNode(Integer.parseInt(a[i])); q.add(node.right); }
            i++;
        }
        return root;
    }

    static long dfs(TreeNode t, long above) {
        if (t == null) return 0;
        long cur = above * 10 + t.val;
        if (t.left == null && t.right == null) return cur;
        return dfs(t.left, cur) + dfs(t.right, cur);
    }

    static long solve(TreeNode root) {
        return dfs(root, 0);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        TreeNode root = build(sc.hasNextLine() ? sc.nextLine() : "");
        System.out.println(solve(root));
    }
}

