        int i = 1;
        while (!q.isEmpty() && i < a.length) {
            TreeNode node = q.poll();
            if (i < a.length && !a[i].equals("null")) { node.left = new TreeNode(Integer.parseInt(a[i])); q.add(node.left); }
            i++;
            if (i < a.length && !a[i].equals("null")) { node.right = new TreeNode(Integer.parseInt(a[i])); q.add(node.right); }
            i++;
        }
        return root;
    }

    static int solve(TreeNode root) {
        int good = 0;
        ArrayDeque<Object[]> st = new ArrayDeque<>();
        st.push(new Object[]{root, Integer.MIN_VALUE});
        while (!st.isEmpty()) {
            Object[] top = st.pop();
            TreeNode t = (TreeNode) top[0];
            int m = (Integer) top[1];
            if (t.val >= m) good++;
            m = Math.max(m, t.val);
            if (t.left != null) st.push(new Object[]{t.left, m});
            if (t.right != null) st.push(new Object[]{t.right, m});
        }
        return good;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        TreeNode root = build(sc.hasNextLine() ? sc.nextLine() : "");
        System.out.println(solve(root));
