a = list(map(int, d[2:2 + n]))

def solve(a, k):
    total = sum(a)
    if total % k:
        return "NO"
    target = total // k
    a = sorted(a, reverse=True)
    if a[0] > target:
        return "NO"
    bucket = [0] * k

    def place(i):
        if i == len(a):
            return True
        for b in range(k):
            if bucket[b] + a[i] > target:
                continue
            if b > 0 and bucket[b] == bucket[b - 1]:
                continue
            bucket[b] += a[i]
            if place(i + 1):
                return True
            bucket[b] -= a[i]
            if bucket[b] == 0:
                break
        return False

    return "YES" if place(0) else "NO"

