public class Main {
    static class Node {
        long sum;
        Node[] next = new Node[26];
    }

    static String solve(String[][] ops) {
        Map<String, Integer> value = new HashMap<>();
        Node root = new Node();
        StringBuilder sb = new StringBuilder();
        for (String[] op : ops) {
            if (op[0].equals("insert")) {
                String key = op[1];
                int val = Integer.parseInt(op[2]);
                int delta = val - value.getOrDefault(key, 0);
                value.put(key, val);
                Node cur = root;
                for (int i = 0; i < key.length(); i++) {
                    int c = key.charAt(i) - 'a';
                    if (cur.next[c] == null) cur.next[c] = new Node();
                    cur = cur.next[c];
                    cur.sum += delta;
                }
            } else {
                Node cur = root;
                String p = op[1];
                for (int i = 0; i < p.length() && cur != null; i++) cur = cur.next[p.charAt(i) - 'a'];
                if (sb.length() > 0) sb.append('\n');
                sb.append(cur == null ? 0 : cur.sum);
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = Integer.parseInt(sc.nextLine().trim());
        String[][] ops = new String[q][];
        for (int i = 0; i < q; i++) ops[i] = sc.nextLine().trim().split("\\s+");
