public class Main {
    static long solve(int[] a, long kk) {
        int k = (int) kk;
        Map<Integer, Integer> cnt = new HashMap<>();
        long sum = 0, best = 0;
        int dups = 0;
        for (int i = 0; i < a.length; i++) {
