d = sys.stdin.read().split()
s = d[0]
k = int(d[1])

def solve(s, k):
    rows = k
    if rows == 1 or rows >= len(s):
        return s
    cycle = 2 * rows - 2
    out = []
    for r in range(rows):
        for j in range(0, len(s), cycle):
            if j + r < len(s):
                out.append(s[j + r])
            if 0 < r < rows - 1 and j + cycle - r < len(s):
                out.append(s[j + cycle - r])
    return "".join(out)

