                int[] cur = q.poll();
                for (int[] d : dirs) {
                    int x = cur[0] + d[0], y = cur[1] + d[1];
                    if (x >= 0 && y >= 0 && x < r && y < c && g[x][y] == '0') { g[x][y] = '1'; q.add(new int[]{x, y}); }
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) {
