public class Main {
    static int solve(int[] a) {
        int n = a.length, k = 0;
        for (int x : a) k += x;
        if (k == 0) return 0;
        int inWin = 0;
        for (int i = 0; i < k; i++) inWin += a[i];
        int best = inWin;
        for (int i = k; i < n + k; i++) {
            inWin += a[i % n] - a[(i - k) % n];
            best = Math.max(best, inWin);
        }
        return k - best;
    }

