def solve(s):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def ways(e):
        res = []
        for i, ch in enumerate(e):
            if ch in "+-*":
                for l in ways(e[:i]):
                    for r in ways(e[i + 1:]):
                        res.append(l + r if ch == "+" else l - r if ch == "-" else l * r)
        return tuple(res) if res else (int(e),)

