import java.util.*;

public class Main {
    static int bit(long n, long k) {
        if (n == 1) return 0;
        long mid = 1L << (n - 1);
        if (k == mid) return 1;
        if (k < mid) return bit(n - 1, k);
        return 1 - bit(n - 1, (1L << n) - k);
    }

    static int solve(long n, long k) {
        return bit(n, k);
    }

