from collections import deque

class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build(tokens):
    if not tokens or tokens[0] == "null":
        return None
    root = TreeNode(int(tokens[0]))
    q = deque([root])
    i = 1
    while q and i < len(tokens):
        node = q.popleft()
        if i < len(tokens) and tokens[i] != "null":
            node.left = TreeNode(int(tokens[i]))
            q.append(node.left)
        i += 1
        if i < len(tokens) and tokens[i] != "null":
            node.right = TreeNode(int(tokens[i]))
            q.append(node.right)
        i += 1
    return root

L = sys.stdin.read().split('\n')
root = build(L[0].split())

def solve(root):
    parent = {root: None}
    level = [root]
    while True:
        nxt = []
        for t in level:
            for c in (t.left, t.right):
                if c:
                    parent[c] = t
                    nxt.append(c)
        if not nxt:
            break
        level = nxt
    nodes = set(level)
    while len(nodes) > 1:
        nodes = {parent[t] for t in nodes}
    return next(iter(nodes)).val

print(solve(root))

