import java.util.*;

public class Main {
    static int largest(int[] h) {
        int n = h.length, best = 0;
        int[] st = new int[n + 1];
        int top = 0;
        for (int i = 0; i <= n; i++) {
            int cur = i == n ? 0 : h[i];
            while (top > 0 && h[st[top - 1]] >= cur) {
                int height = h[st[--top]];
                int left = top == 0 ? -1 : st[top - 1];
                best = Math.max(best, height * (i - left - 1));
            }
            st[top++] = i;
        }
        return best;
    }

