import java.util.*;

public class Main {
    static long solve(int[] a, long target) {
        int total = 0;
        for (int x : a) total += x;
        if (Math.abs(target) > total || (total + target) % 2 != 0) return 0;
        int p = (int) ((total + target) / 2);
        long[] ways = new long[p + 1];
        ways[0] = 1;
        for (int x : a)
            for (int s = p; s >= x; s--) ways[s] += ways[s - x];
        return ways[p];
    }

