n = int(sys.stdin.read().split()[0])

def solve(n):
    def digits_upto(x):
        total, length, low = 0, 1, 1
        while low <= x:
            total += (min(x, low * 10 - 1) - low + 1) * length
            length += 1
            low *= 10
        return total

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if digits_upto(mid) >= n:
            hi = mid
        else:
            lo = mid + 1
    return int(str(lo)[n - digits_upto(lo - 1) - 1])

