import java.util.*;

public class Main {
    static long solve(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[n];
        for (int[] e : edges) { adj.get(e[0]).add(new int[]{e[1], e[2]}); indeg[e[1]]++; }
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) q.add(i);
        long[] best = new long[n];
        long answer = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            answer = Math.max(answer, best[u]);
            for (int[] e : adj.get(u)) {
                best[e[0]] = Math.max(best[e[0]], best[u] + e[1]);
                if (--indeg[e[0]] == 0) q.add(e[0]);
            }
        }
        return answer;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        int[][] edges = new int[m][3];
        for (int i = 0; i < m; i++) for (int j = 0; j < 3; j++) edges[i][j] = sc.nextInt();
        System.out.println(solve(n, edges));
    }
}

