import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

d = sys.stdin.read().split()
n = int(d[0])
a = list(map(int, d[1:1 + n]))

def solve(a):
    root = None
    left, right, val = {}, {}, {}
    for i, x in enumerate(a):
        val[i] = x
        if root is None:
            root = i
            continue
        cur = root
        while True:
            side = left if x < val[cur] else right
            if cur in side:
                cur = side[cur]
            else:
                side[cur] = i
                break
    out = []

    def post(u):
        if u in left:
            post(left[u])
        if u in right:
            post(right[u])
        out.append(val[u])

    post(root)
    return " ".join(map(str, out))

print(solve(a))

