import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    static TreeNode build(String line) {
        String t = line.trim();
        if (t.isEmpty()) return null;
        String[] a = t.split("\\s+");
        if (a[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(a[0]));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < a.length) {
            TreeNode node = q.poll();
            if (i < a.length && !a[i].equals("null")) { node.left = new TreeNode(Integer.parseInt(a[i])); q.add(node.left); }
            i++;
            if (i < a.length && !a[i].equals("null")) { node.right = new TreeNode(Integer.parseInt(a[i])); q.add(node.right); }
            i++;
        }
        return root;
    }

    static String solve(TreeNode root, int target, int k) {
        Map<TreeNode, TreeNode> parent = new HashMap<>();
        TreeNode start = null;
        ArrayDeque<TreeNode> st = new ArrayDeque<>();
        st.push(root);
        while (!st.isEmpty()) {
            TreeNode u = st.pop();
            if (u.val == target) start = u;
            if (u.left != null) { parent.put(u.left, u); st.push(u.left); }
            if (u.right != null) { parent.put(u.right, u); st.push(u.right); }
        }
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        Set<TreeNode> seen = new HashSet<>();
        q.add(start);
        seen.add(start);
        for (int d = 0; d < k && !q.isEmpty(); d++)
            for (int size = q.size(); size > 0; size--) {
                TreeNode u = q.poll();
                for (TreeNode v : new TreeNode[]{u.left, u.right, parent.get(u)})
                    if (v != null && seen.add(v)) q.add(v);
            }
        if (q.isEmpty()) return "NONE";
        List<Integer> vals = new ArrayList<>();
        for (TreeNode t : q) vals.add(t.val);
        Collections.sort(vals);
        StringBuilder sb = new StringBuilder();
        for (int v : vals) { if (sb.length() > 0) sb.append(' '); sb.append(v); }
        return sb.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        TreeNode root = build(sc.hasNextLine() ? sc.nextLine() : "");
        int x = sc.nextInt(), y = sc.nextInt();
        System.out.println(solve(root, x, y));
    }
}

