    present = set(words)

    @lru_cache(maxsize=None)
    def longest_ending(w):
        best = 1
        for i in range(len(w)):
            shorter = w[:i] + w[i + 1:]
            if shorter in present:
                best = max(best, 1 + longest_ending(shorter))
        return best

