import java.util.*;

public class Main {
    static int solve(String s, int[][] p) {
        int n = s.length();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[n];
        for (int[] e : p) { adj.get(e[0]).add(e[1]); indeg[e[1]]++; }
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) q.add(i);
        int[][] cnt = new int[n][26];
        int seen = 0, best = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            seen++;
            best = Math.max(best, ++cnt[u][s.charAt(u) - 'a']);
            for (int v : adj.get(u)) {
                for (int c = 0; c < 26; c++) cnt[v][c] = Math.max(cnt[v][c], cnt[u][c]);
                if (--indeg[v] == 0) q.add(v);
            }
        }
        return seen == n ? best : -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int m = sc.nextInt();
        int[][] p = new int[m][2];
        for (int i = 0; i < m; i++) { p[i][0] = sc.nextInt(); p[i][1] = sc.nextInt(); }
        System.out.println(solve(s, p));
    }
}

