def solve(a):
    val, left, right = [], {}, {}
    for i, x in enumerate(a):
        val.append(x)
        if i == 0:
            continue
        cur = 0
        while True:
            side = left if x < val[cur] else right
            if cur in side:
                cur = side[cur]
            else:
                side[cur] = i
                break
    order = []
    stack = [0]
    while stack:
        u = stack.pop()
        order.append(val[u])
        if u in right:
            stack.append(right[u])
        if u in left:
            stack.append(left[u])
    return "YES" if order == list(a) else "NO"

