    lines = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]

    def won(b):
        return any(b[i] != "." and b[i] == b[j] == b[k] for i, j, k in lines)

    seen = {"........."}
    frontier = ["........."]
    while frontier:
        nxt = []
        for b in frontier:
            if won(b):
                continue
            player = "X" if b.count("X") == b.count("O") else "O"
            for i in range(9):
                if b[i] == ".":
                    nb = b[:i] + player + b[i + 1:]
                    if nb not in seen:
                        seen.add(nb)
                        nxt.append(nb)
        frontier = nxt
    return "YES" if board in seen else "NO"

