import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

d = sys.stdin.read().split()
r, c = int(d[0]), int(d[1])
g = [list(row) for row in d[2:2 + r]]

def solve(g):
    r, c = len(g), len(g[0])
    seen = set()
    closed = 0
    for i in range(r):
        for j in range(c):
            if g[i][j] != "L" or (i, j) in seen:
                continue
            seen.add((i, j))
            stack = [(i, j)]
            touches = False
            while stack:
                x, y = stack.pop()
                if x in (0, r - 1) or y in (0, c - 1):
                    touches = True
                for a, b in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= a < r and 0 <= b < c and g[a][b] == "L" and (a, b) not in seen:
                        seen.add((a, b))
                        stack.append((a, b))
            if not touches:
                closed += 1
    return closed

print(solve(g))

