import java.util.*;

public class Main {
    static void sink(char[][] g, int si, int sj) {
        int r = g.length, c = g[0].length;
        ArrayDeque<int[]> st = new ArrayDeque<>();
        g[si][sj] = 'W';
        st.push(new int[]{si, sj});
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!st.isEmpty()) {
            int[] cur = st.pop();
            for (int[] d : dirs) {
                int a = cur[0] + d[0], b = cur[1] + d[1];
                if (a < 0 || b < 0 || a >= r || b >= c || g[a][b] != 'L') continue;
                g[a][b] = 'W';
                st.push(new int[]{a, b});
            }
        }
    }

    static int solve(char[][] g) {
        int r = g.length, c = g[0].length;
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++)
                if ((i == 0 || j == 0 || i == r - 1 || j == c - 1) && g[i][j] == 'L') sink(g, i, j);
        int closed = 0;
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++)
                if (g[i][j] == 'L') { sink(g, i, j); closed++; }
        return closed;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        char[][] g = new char[r][];
