import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

d = list(map(int, sys.stdin.read().split()))
r, c = d[0], d[1]
m = [d[2 + i * c:2 + (i + 1) * c] for i in range(r)]

def solve(m):
    r, c = len(m), len(m[0])
    NEG = float("-inf")

    def survives(h):
        best = [[NEG] * c for _ in range(r)]
        for i in range(r):
            for j in range(c):
                if i == 0 and j == 0:
                    before = h
                else:
                    before = max(best[i - 1][j] if i else NEG, best[i][j - 1] if j else NEG)
                if before == NEG:
                    continue
                after = before + m[i][j]
                if after >= 1:
                    best[i][j] = after
        return best[r - 1][c - 1] != NEG

    lo, hi = 1, 1 + sum(abs(v) for row in m for v in row)
    while lo < hi:
        mid = (lo + hi) // 2
        if survives(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

print(solve(m))

