import java.util.*;

public class Main {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int val, ListNode next) { this.val = val; this.next = next; }
    }

    static ListNode build(int[] vals) {
        ListNode head = null;
        for (int i = vals.length - 1; i >= 0; i--) head = new ListNode(vals[i], head);
        return head;
    }

    static String dump(ListNode head) {
        StringBuilder sb = new StringBuilder();
        for (ListNode p = head; p != null; p = p.next) { if (sb.length() > 0) sb.append(' '); sb.append(p.val); }
        return sb.length() == 0 ? "EMPTY" : sb.toString();
    }

    static ListNode solve(ListNode head) {
        if (head.val >= 5) head = new ListNode(0, head);
        for (ListNode p = head; p != null; p = p.next) {
            int carry = (p.next != null && p.next.val >= 5) ? 1 : 0;
            p.val = (p.val * 2) % 10 + carry;
        }
        return head;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) vals[i] = sc.nextInt();
        ListNode head = build(vals);
        System.out.println(dump(solve(head)));
    }
}

