public class Main {
    static long solve(long nn) {
        final long MOD = 1_000_000_007L;
        int n = (int) nn;
        long[] full = new long[n + 2], part = new long[n + 2];
        full[0] = 1;
        full[1] = 1;
        for (int i = 2; i <= n; i++) {
            full[i] = (full[i - 1] + full[i - 2] + 2 * part[i - 1]) % MOD;
            part[i] = (part[i - 1] + full[i - 2]) % MOD;
        }
        return full[n];
    }

