public class Main {
    static int solve(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], 1});
            adj.get(e[1]).add(new int[]{e[0], 0});
        }
        boolean[] seen = new boolean[n];
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        seen[0] = true;
        int flips = 0;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int[] e : adj.get(u)) {
                if (seen[e[0]]) continue;
                seen[e[0]] = true;
                flips += e[1];
                stack.push(e[0]);
            }
        }
        return flips;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) { edges[i][0] = sc.nextInt(); edges[i][1] = sc.nextInt(); }
        System.out.println(solve(n, edges));
    }
}

