import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

d = list(map(int, sys.stdin.read().split()))
n, m, k = d[0], d[1], d[2]
edges = [(d[3 + 3 * i], d[4 + 3 * i], d[5 + 3 * i]) for i in range(m)]

def solve(n, edges, k):
    from collections import deque
    adj = defaultdict(list)
    next_id = n
    for u, v, cnt in edges:
        chain = [u] + list(range(next_id, next_id + cnt)) + [v]
        next_id += cnt
        for a, b in zip(chain, chain[1:]):
            adj[a].append(b)
            adj[b].append(a)
    dist = {0: 0}
    q = deque([0])
    while q:
        x = q.popleft()
        if dist[x] == k:
            continue
        for y in adj[x]:
            if y not in dist:
                dist[y] = dist[x] + 1
                q.append(y)
    return len(dist)

print(solve(n, edges, k))

