import java.util.*;

public class Main {
    static long solve(int[][] m) {
        int n = m.length;
        long[] prev = new long[n];
        for (int j = 0; j < n; j++) prev[j] = m[0][j];
        for (int i = 1; i < n; i++) {
            long[] cur = new long[n];
            for (int j = 0; j < n; j++) {
                long best = prev[j];
                if (j > 0) best = Math.min(best, prev[j - 1]);
                if (j < n - 1) best = Math.min(best, prev[j + 1]);
                cur[j] = m[i][j] + best;
            }
            prev = cur;
        }
        long ans = Long.MAX_VALUE;
        for (long v : prev) ans = Math.min(ans, v);
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        int[][] m = new int[r][c];
        for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) m[i][j] = sc.nextInt();
        System.out.println(solve(m));
    }
}

