import java.util.*;

public class Main {
    static char[][] grid;

    static long dfs(int i, int j, int remaining) {
        if (grid[i][j] == 'E') return remaining == 0 ? 1 : 0;
        char saved = grid[i][j];
        grid[i][j] = '#';
        long ways = 0;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] d : dirs) {
            int x = i + d[0], y = j + d[1];
            if (x >= 0 && y >= 0 && x < grid.length && y < grid[0].length && grid[x][y] != '#')
                ways += dfs(x, y, remaining - 1);
        }
        grid[i][j] = saved;
        return ways;
    }

    static long solve(char[][] g) {
        grid = g;
        int free = 0, si = 0, sj = 0;
        for (int i = 0; i < g.length; i++)
            for (int j = 0; j < g[0].length; j++) {
                if (g[i][j] != '#') free++;
                if (g[i][j] == 'S') { si = i; sj = j; }
            }
        return dfs(si, sj, free - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        char[][] g = new char[r][];
        for (int i = 0; i < r; i++) g[i] = sc.next().toCharArray();
        System.out.println(solve(g));
    }
}

