n, k = int(d[0]), int(d[1])
a = list(map(int, d[2:2 + n]))

def solve(a, k):
    from functools import lru_cache
    n = len(a)

    @lru_cache(maxsize=None)
    def best(used, power, score):
        result = score
        for i in range(n):
            if used >> i & 1:
                continue
            if power >= a[i]:
                result = max(result, best(used | 1 << i, power - a[i], score + 1))
            if score >= 1:
                result = max(result, best(used | 1 << i, power + a[i], score - 1))
        return result

    return best(0, k, 0)

print(solve(a, k))

