ops = [L[1 + i].split() for i in range(q)]

def solve(ops):
    seen = set()
    out = []
    for op in ops:
        if op[0] == "add":
            seen.add(int(op[1]))
            continue
        parts = []
        start = prev = None
        for v in sorted(seen):
            if start is None:
                start = prev = v
            elif v == prev + 1:
                prev = v
            else:
                parts.append(f"{start}-{prev}")
                start = prev = v
        if start is not None:
            parts.append(f"{start}-{prev}")
        out.append(" ".join(parts) if parts else "EMPTY")
    return "\n".join(out)

