nearest-exit-maze.python:
import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

d = sys.stdin.read().split()
r, c = int(d[0]), int(d[1])
g = [list(row) for row in d[2:2 + r]]

def solve(g):
    from collections import deque
    r, c = len(g), len(g[0])
    dist = {}
    q = deque()
    for i in range(r):
        for j in range(c):
            if g[i][j] == "." and (i in (0, r - 1) or j in (0, c - 1)):
                dist[(i, j)] = 0
                q.append((i, j))
    while q:
        i, j = q.popleft()
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < r and 0 <= b < c and g[a][b] != "+" and (a, b) not in dist:
                dist[(a, b)] = dist[(i, j)] + 1
                if g[a][b] == "E":
                    return dist[(a, b)]
                q.append((a, b))
    return -1

print(solve(g))

