import java.util.*;

public class Main {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int val, ListNode next) { this.val = val; this.next = next; }
    }

    static ListNode build(int[] vals) {
        ListNode head = null;
        for (int i = vals.length - 1; i >= 0; i--) head = new ListNode(vals[i], head);
        return head;
    }

    static String dump(ListNode head) {
        StringBuilder sb = new StringBuilder();
        for (ListNode p = head; p != null; p = p.next) { if (sb.length() > 0) sb.append(' '); sb.append(p.val); }
        return sb.length() == 0 ? "EMPTY" : sb.toString();
    }

    static ListNode reverse(ListNode head) {
        ListNode prev = null;
        while (head != null) { ListNode next = head.next; head.next = prev; prev = head; head = next; }
        return prev;
    }

    static ListNode solve(ListNode head) {
        head = reverse(head);
        ListNode p = head;
        while (p.next != null) {
            if (p.next.val < p.val) p.next = p.next.next;
            else p = p.next;
        }
        return reverse(head);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) vals[i] = sc.nextInt();
        ListNode head = build(vals);
        System.out.println(dump(solve(head)));
    }
}

