import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    static TreeNode build(String line) {
        String t = line.trim();
        if (t.isEmpty()) return null;
        String[] a = t.split("\\s+");
        if (a[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(a[0]));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < a.length) {
            TreeNode node = q.poll();
            if (i < a.length && !a[i].equals("null")) { node.left = new TreeNode(Integer.parseInt(a[i])); q.add(node.left); }
            i++;
            if (i < a.length && !a[i].equals("null")) { node.right = new TreeNode(Integer.parseInt(a[i])); q.add(node.right); }
            i++;
        }
        return root;
    }

    static String solve(TreeNode root, int x, int y) {
        int dx = -1, dy = -2;
        TreeNode px = null, py = null;
        ArrayDeque<Object[]> st = new ArrayDeque<>();
        st.push(new Object[]{root, null, 0});
        while (!st.isEmpty()) {
            Object[] e = st.pop();
            TreeNode t = (TreeNode) e[0];
            int d = (int) e[2];
            if (t.val == x) { px = (TreeNode) e[1]; dx = d; }
            if (t.val == y) { py = (TreeNode) e[1]; dy = d; }
            if (t.left != null) st.push(new Object[]{t.left, t, d + 1});
            if (t.right != null) st.push(new Object[]{t.right, t, d + 1});
        }
        return dx == dy && px != py ? "YES" : "NO";
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        TreeNode root = build(sc.hasNextLine() ? sc.nextLine() : "");
        int x = sc.nextInt(), y = sc.nextInt();
        System.out.println(solve(root, x, y));
    }
}

