        self.next = None
        self.random = None

d = list(map(int, sys.stdin.read().split()))
n = d[0]
nodes = [Node(d[1 + 2 * i]) for i in range(n)]
for i in range(n):
    if i + 1 < n:
        nodes[i].next = nodes[i + 1]
    r = d[2 + 2 * i]
    nodes[i].random = nodes[r] if r >= 0 else None
head = nodes[0] if n else None

def dump(copy):
