    order = []
    p = copy
    while p is not None:
        if id(p) in originals:
            return "SHARED"
        order.append(p)
        p = p.next
    if not order:
        return "EMPTY"
    index = {id(x): i for i, x in enumerate(order)}
    out = []
    for x in order:
        if x.random is None:
            out.append(str(x.val) + " -1")
        elif id(x.random) in index:
            out.append(str(x.val) + " " + str(index[id(x.random)]))
        else:
            return "RANDOM OUTSIDE COPY"
    return "\n".join(out)

def solve(head):
