        copy[id(p)] = Node(p.val)
        p = p.next
    p = head
    while p is not None:
        c = copy[id(p)]
        c.next = copy[id(p.next)] if p.next is not None else None
        c.random = copy[id(p.random)] if p.random is not None else None
        p = p.next
    return copy[id(head)]

