import java.util.*;

public class Main {
    static class Node {
        int val;
        Node next, random;
        Node(int val) { this.val = val; }
    }

    static Node[] originals;

    static String dump(Node copy) {
        Set<Node> orig = Collections.newSetFromMap(new IdentityHashMap<>());
        orig.addAll(Arrays.asList(originals));
        List<Node> order = new ArrayList<>();
        for (Node p = copy; p != null; p = p.next) {
            if (orig.contains(p)) return "SHARED";
            order.add(p);
        }
        if (order.isEmpty()) return "EMPTY";
        Map<Node, Integer> index = new IdentityHashMap<>();
        for (int i = 0; i < order.size(); i++) index.put(order.get(i), i);
        StringBuilder sb = new StringBuilder();
        for (Node x : order) {
            if (sb.length() > 0) sb.append('\n');
            if (x.random == null) sb.append(x.val).append(" -1");
            else if (index.containsKey(x.random)) sb.append(x.val).append(' ').append(index.get(x.random));
            else return "RANDOM OUTSIDE COPY";
        }
        return sb.toString();
    }

    static Node solve(Node head) {
        if (head == null) return null;
        for (Node p = head; p != null; p = p.next.next) {     // weave: A -> A' -> B -> B'
            Node c = new Node(p.val);
            c.next = p.next;
            p.next = c;
        }
        for (Node p = head; p != null; p = p.next.next)
            p.next.random = p.random == null ? null : p.random.next;
        Node copyHead = head.next;
        for (Node p = head; p != null; p = p.next) {           // unweave both lists
            Node c = p.next;
            p.next = c.next;
            c.next = c.next == null ? null : c.next.next;
        }
        return copyHead;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        originals = new Node[n];
        int[] rnd = new int[n];
        for (int i = 0; i < n; i++) { originals[i] = new Node(sc.nextInt()); rnd[i] = sc.nextInt(); }
        for (int i = 0; i < n; i++) {
            if (i + 1 < n) originals[i].next = originals[i + 1];
            originals[i].random = rnd[i] >= 0 ? originals[rnd[i]] : null;
        }
        Node head = n > 0 ? originals[0] : null;
        System.out.println(dump(solve(head)));
    }
}

