class Node:
    def __init__(self, val):
        self.val = val
        self.prev = None
        self.next = None
        self.child = None

d = list(map(int, sys.stdin.read().split()))
n = d[0]
nodes = [Node(d[1 + 3 * i]) for i in range(n)]
for i in range(n):
    nx, ch = d[2 + 3 * i], d[3 + 3 * i]
    if nx >= 0:
        nodes[i].next = nodes[nx]
        nodes[nx].prev = nodes[i]
    if ch >= 0:
        nodes[i].child = nodes[ch]
head = nodes[0] if n else None

def dump(h):
    if h is None:
        return "EMPTY"
    out, prev, p = [], None, h
    while p is not None:
        if p.child is not None:
            return "CHILD LEFT AT " + str(p.val)
        if p.prev is not prev:
            return "BAD PREV AT " + str(p.val)
        out.append(str(p.val))
        prev, p = p, p.next
    return " ".join(out)

def solve(head):
    stack = []
    p = head
    while p is not None:
        if p.child is not None:
            if p.next is not None:
                stack.append(p.next)
            p.next = p.child
            p.child.prev = p
            p.child = None
        if p.next is None and stack:
            nxt = stack.pop()
            p.next = nxt
            nxt.prev = p
        p = p.next
    return head

print(dump(solve(head)))

