import java.util.*;

public class Main {
    static class Node {
        int val;
        Node prev, next, child;
        Node(int val) { this.val = val; }
    }

    static String dump(Node h) {
        if (h == null) return "EMPTY";
        StringBuilder sb = new StringBuilder();
        Node prev = null;
        for (Node p = h; p != null; prev = p, p = p.next) {
            if (p.child != null) return "CHILD LEFT AT " + p.val;
            if (p.prev != prev) return "BAD PREV AT " + p.val;
            if (sb.length() > 0) sb.append(' ');
            sb.append(p.val);
        }
        return sb.toString();
    }

    static Node solve(Node head) {
        flatten(head);
        return head;
    }

    static Node flatten(Node h) {
        Node p = h, last = h;
        while (p != null) {
            Node next = p.next;
            if (p.child != null) {
                Node tail = flatten(p.child);
                p.next = p.child;
                p.child.prev = p;
                p.child = null;
                tail.next = next;
                if (next != null) next.prev = tail;
                last = tail;
            } else {
                last = p;
            }
            p = next;
        }
        return last;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Node[] nodes = new Node[n];
        int[] nx = new int[n], ch = new int[n];
