import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    static String level(TreeNode root) {
        if (root == null) return "EMPTY";
        List<String> out = new ArrayList<>();
        LinkedList<TreeNode> q = new LinkedList<>();   // LinkedList: ArrayDeque rejects null
        q.add(root);
        while (!q.isEmpty()) {
            TreeNode node = q.poll();
            if (node == null) { out.add("null"); continue; }
            out.add(String.valueOf(node.val));
            q.add(node.left);
            q.add(node.right);
        }
        while (!out.isEmpty() && out.get(out.size() - 1).equals("null")) out.remove(out.size() - 1);
        return String.join(" ", out);
    }

    static TreeNode solve(int[] pre, int[] ino) {
        // Iterative: a stack of nodes still waiting for a right child.
        if (pre.length == 0) return null;
        TreeNode root = new TreeNode(pre[0]);
        ArrayDeque<TreeNode> st = new ArrayDeque<>();
        st.push(root);
        int j = 0;
        for (int i = 1; i < pre.length; i++) {
            TreeNode node = new TreeNode(pre[i]);
            TreeNode parent = null;
            while (!st.isEmpty() && st.peek().val == ino[j]) { parent = st.pop(); j++; }
            if (parent != null) parent.right = node;
            else st.peek().left = node;
            st.push(node);
        }
        return root;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] pre = new int[n], ino = new int[n];
        for (int i = 0; i < n; i++) pre[i] = sc.nextInt();
        for (int i = 0; i < n; i++) ino[i] = sc.nextInt();
        System.out.println(level(solve(pre, ino)));
    }
}

