import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    static TreeNode build(String line) {
        String t = line.trim();
        if (t.isEmpty()) return null;
        String[] a = t.split("\\s+");
        if (a[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(a[0]));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < a.length) {
            TreeNode node = q.poll();
            if (i < a.length && !a[i].equals("null")) { node.left = new TreeNode(Integer.parseInt(a[i])); q.add(node.left); }
            i++;
            if (i < a.length && !a[i].equals("null")) { node.right = new TreeNode(Integer.parseInt(a[i])); q.add(node.right); }
            i++;
        }
        return root;
    }

    static class BSTIterator {
        private final ArrayDeque<TreeNode> st = new ArrayDeque<>();
        BSTIterator(TreeNode root) { pushLeft(root); }
        private void pushLeft(TreeNode n) { for (; n != null; n = n.left) st.push(n); }
        boolean hasNext() { return !st.isEmpty(); }
        int next() {
            TreeNode n = st.pop();
            pushLeft(n.right);
            return n.val;
        }
    }

    static String solve(TreeNode root, String[] ops) {
        BSTIterator it = new BSTIterator(root);
        StringBuilder sb = new StringBuilder();
        for (String op : ops) {
            if (sb.length() > 0) sb.append('\n');
            if (op.equals("hasNext")) sb.append(it.hasNext());
            else sb.append(it.next());
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        TreeNode root = build(sc.hasNextLine() ? sc.nextLine() : "");
        int q = Integer.parseInt(sc.nextLine().trim());
        String[] ops = new String[q];
        for (int i = 0; i < q; i++) ops[i] = sc.nextLine().trim();
