    nodes[u].neighbors.append(nodes[v])
    nodes[v].neighbors.append(nodes[u])
node = nodes[0]

def dump(copy):
    if copy is None:
        return "NULL"
    originals = set(id(x) for x in nodes)
    seen = {id(copy)}
    order = [copy]
    i = 0
    while i < len(order):
        for nb in order[i].neighbors:
            if id(nb) not in seen:
                seen.add(id(nb))
                order.append(nb)
        i += 1
    if any(id(x) in originals for x in order):
        return "SHARED"
    order.sort(key=lambda x: x.val)
    return "\n".join(str(x.val) + ":" + "".join(" " + str(v) for v in sorted(nb.val for nb in x.neighbors))
                     for x in order)

def solve(node):
    if node is None:
        return None
    copy = {id(node): Node(node.val)}
    q = deque([node])
    while q:
        u = q.popleft()
        for v in u.neighbors:
            if id(v) not in copy:
                copy[id(v)] = Node(v.val)
                q.append(v)
            copy[id(u)].neighbors.append(copy[id(v)])
    return copy[id(node)]

print(dump(solve(node)))

