import java.util.*;

public class Main {
    static class Node {
        int val;
        List<Node> neighbors = new ArrayList<>();
        Node(int val) { this.val = val; }
    }

    static Node[] originals;

    static String dump(Node copy) {
        if (copy == null) return "NULL";
        Set<Node> orig = Collections.newSetFromMap(new IdentityHashMap<>());
        orig.addAll(Arrays.asList(originals));
        Set<Node> seen = Collections.newSetFromMap(new IdentityHashMap<>());
        List<Node> order = new ArrayList<>();
        order.add(copy);
        seen.add(copy);
        for (int i = 0; i < order.size(); i++)
            for (Node nb : order.get(i).neighbors)
                if (seen.add(nb)) order.add(nb);
        for (Node x : order) if (orig.contains(x)) return "SHARED";
        order.sort(Comparator.comparingInt(x -> x.val));
        StringBuilder sb = new StringBuilder();
        for (Node x : order) {
            if (sb.length() > 0) sb.append('\n');
            sb.append(x.val).append(':');
            List<Integer> vs = new ArrayList<>();
            for (Node nb : x.neighbors) vs.add(nb.val);
            Collections.sort(vs);
            for (int v : vs) sb.append(' ').append(v);
        }
        return sb.toString();
    }

    static Map<Node, Node> made = new IdentityHashMap<>();

    static Node solve(Node node) {
        if (node == null) return null;
        Node have = made.get(node);
        if (have != null) return have;
        Node c = new Node(node.val);
        made.put(node, c);                  // record BEFORE recursing, or a cycle never ends
        for (Node nb : node.neighbors) c.neighbors.add(solve(nb));
        return c;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        originals = new Node[n];
        for (int i = 0; i < n; i++) originals[i] = new Node(i);
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt(), v = sc.nextInt();
            originals[u].neighbors.add(originals[v]);
            originals[v].neighbors.add(originals[u]);
        }
        Node node = originals[0];
        System.out.println(dump(solve(node)));
    }
}

