import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

d = list(map(int, sys.stdin.read().split()))
n, m = d[0], d[1]
edges = [(d[2 + 3 * i], d[3 + 3 * i], d[4 + 3 * i]) for i in range(m)]

def solve(n, edges):
    m = len(edges)
    order = sorted(range(m), key=lambda e: edges[e][2])

    def kruskal(skip, force):
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        weight = used = 0
        if force >= 0:
            u, v, w = edges[force]
            parent[find(u)] = find(v)
            weight += w
            used += 1
        for e in order:
            if e == skip:
                continue
            u, v, w = edges[e]
            ru, rv = find(u), find(v)
            if ru != rv:
                parent[ru] = rv
                weight += w
                used += 1
        return weight if used == n - 1 else float("inf")

    base = kruskal(-1, -1)
    critical, pseudo = [], []
    for e in range(m):
        if kruskal(e, -1) > base:
            critical.append(e)
        elif kruskal(-1, e) == base:
            pseudo.append(e)
    fmt = lambda xs: " ".join(map(str, xs)) if xs else "none"
    return fmt(critical) + "\n" + fmt(pseudo)

print(solve(n, edges))

