import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

d = list(map(int, sys.stdin.read().split()))
n, m, q = d[0], d[1], d[2]
edges = [(d[3 + 3 * i], d[4 + 3 * i], d[5 + 3 * i]) for i in range(m)]
queries = [(d[3 + 3 * m + 2 * i], d[4 + 3 * m + 2 * i]) for i in range(q)]

def solve(n, edges, queries):
    INF = float("inf")
    cache = {}

    def from_source(s):
        dist = [INF] * n
        dist[s] = 0
        for _ in range(n - 1):
            changed = False
            for u, v, w in edges:
                if dist[u] != INF and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    changed = True
            if not changed:
                break
        return dist

    out = []
    for a, b in queries:
        if a not in cache:
            cache[a] = from_source(a)
        d = cache[a][b]
        out.append("INF" if d == INF else str(d))
    return "\n".join(out)

print(solve(n, edges, queries))

