public class Main {
    static long solve(int[][] p, int W) {
        int n = p.length;
        long[][] dp = new long[n + 1][W + 1];
        for (int i = 1; i <= n; i++) {
            int w = p[i - 1][0], v = p[i - 1][1];
            for (int c = 0; c <= W; c++) {
                dp[i][c] = dp[i - 1][c];
                if (c >= w) dp[i][c] = Math.max(dp[i][c], dp[i - 1][c - w] + v);
            }
        }
        return dp[n][W];
    }

    public static void main(String[] args) {
