import java.util.*;

public class Main {
    static String solve(int n, int[][] edges) {
        int[] deg = new int[n];
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            deg[e[0]]++; deg[e[1]]++;
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int odd = 0, start = -1, withEdges = 0;
        for (int v = 0; v < n; v++) {
            if (deg[v] % 2 == 1) odd++;
            if (deg[v] > 0) { withEdges++; if (start < 0) start = v; }
        }
        if (odd != 0 && odd != 2) return "false";
        boolean[] seen = new boolean[n];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(start);
        seen[start] = true;
        int reached = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            reached++;
            for (int v : adj.get(u)) if (!seen[v]) { seen[v] = true; q.add(v); }
        }
        return reached == withEdges ? "true" : "false";
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) { edges[i][0] = sc.nextInt(); edges[i][1] = sc.nextInt(); }
        System.out.println(solve(n, edges));
    }
}

