import java.util.*;

public class Main {
    static long solve(int[][] cost) {
        int n = cost.length;
        long[] dp = new long[1 << n];
        Arrays.fill(dp, Long.MAX_VALUE);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] == Long.MAX_VALUE) continue;
            int worker = Integer.bitCount(mask);
            if (worker == n) continue;
            for (int j = 0; j < n; j++)
                if ((mask >> j & 1) == 0)
                    dp[mask | 1 << j] = Math.min(dp[mask | 1 << j], dp[mask] + cost[worker][j]);
        }
        return dp[(1 << n) - 1];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        int[][] m = new int[r][c];
        for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) m[i][j] = sc.nextInt();
        System.out.println(solve(m));
    }
}

