import java.util.*;

public class Main {
    static long solve(int n, int[][] edges) {
        final int INF = 1_000_000;
        int[][] d = new int[n][n];
        for (int[] row : d) Arrays.fill(row, INF);
        for (int i = 0; i < n; i++) d[i][i] = 0;
        for (int[] e : edges) { d[e[0]][e[1]] = 1; d[e[1]][e[0]] = 1; }
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    d[i][j] = Math.min(d[i][j], d[i][k] + d[k][j]);
        int[][] dp = new int[1 << n][n];
        for (int[] row : dp) Arrays.fill(row, INF);
        for (int v = 0; v < n; v++) dp[1 << v][v] = 0;
        for (int mask = 1; mask < (1 << n); mask++)
            for (int v = 0; v < n; v++) {
                if (dp[mask][v] == INF) continue;
                for (int w = 0; w < n; w++)
                    if ((mask >> w & 1) == 0)
                        dp[mask | 1 << w][w] = Math.min(dp[mask | 1 << w][w], dp[mask][v] + d[v][w]);
            }
        int best = INF;
        for (int v = 0; v < n; v++) best = Math.min(best, dp[(1 << n) - 1][v]);
        return best;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) { edges[i][0] = sc.nextInt(); edges[i][1] = sc.nextInt(); }
        System.out.println(solve(n, edges));
    }
}

