public class Main {
    static String solve(int n, int[][] edges, int[][] queries) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int[] tin = new int[n], tout = new int[n], parent = new int[n], iter = new int[n];
        int timer = 0;
        int[] stack = new int[n + 1];
        int top = 0;
        stack[top] = 0;
        parent[0] = -1;
        tin[0] = timer++;
        while (top >= 0) {
            int u = stack[top];
            if (iter[u] < g.get(u).size()) {
                int w = g.get(u).get(iter[u]++);
                if (w == parent[u]) continue;
                parent[w] = u;
                tin[w] = timer++;
                stack[++top] = w;
            } else {
                tout[u] = timer++;
                top--;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0], b = queries[i][1];
            if (i > 0) sb.append('\n');
            sb.append(tin[a] <= tin[b] && tout[b] <= tout[a] ? "YES" : "NO");
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), q = sc.nextInt();
        int[][] edges = new int[n - 1][2];
        for (int i = 0; i < n - 1; i++) { edges[i][0] = sc.nextInt(); edges[i][1] = sc.nextInt(); }
