import java.util.*;

public class Main {
    static String solve(int n, int[][] edges, int[][] queries) {
        int[] head = new int[n], nxt = new int[2 * Math.max(1, n - 1)];
        int[] to = new int[2 * Math.max(1, n - 1)], cost = new int[2 * Math.max(1, n - 1)];
        Arrays.fill(head, -1);
        int ec = 0;
        for (int[] e : edges) {
            to[ec] = e[1]; cost[ec] = e[2]; nxt[ec] = head[e[0]]; head[e[0]] = ec++;
            to[ec] = e[0]; cost[ec] = e[2]; nxt[ec] = head[e[1]]; head[e[1]] = ec++;
        }
        int LOG = 1;
        while ((1 << LOG) < Math.max(2, n)) LOG++;
        LOG++;
        int[][] up = new int[LOG][n];
        for (int[] row : up) Arrays.fill(row, -1);
        int[] depth = new int[n];
        long[] dist = new long[n];
        int[] order = new int[n];
        boolean[] seen = new boolean[n];
        int h = 0, t = 0;
        order[t++] = 0;
        seen[0] = true;
        while (h < t) {
            int u = order[h++];
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int w = to[e];
                if (seen[w]) continue;
                seen[w] = true;
                up[0][w] = u;
                depth[w] = depth[u] + 1;
                dist[w] = dist[u] + cost[e];
                order[t++] = w;
            }
        }
        for (int j = 1; j < LOG; j++)
            for (int v = 0; v < n; v++) {
                int mid = up[j - 1][v];
                up[j][v] = mid < 0 ? -1 : up[j - 1][mid];
            }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0], b = queries[i][1];
            int x = a, y = b;
            if (depth[x] < depth[y]) { int tmp = x; x = y; y = tmp; }
            int diff = depth[x] - depth[y];
            for (int j = 0; diff > 0; j++, diff >>= 1) if ((diff & 1) == 1) x = up[j][x];
            int m;
            if (x == y) {
                m = x;
            } else {
                for (int j = LOG - 1; j >= 0; j--)
                    if (up[j][x] != up[j][y]) { x = up[j][x]; y = up[j][y]; }
                m = up[0][x];
            }
            if (i > 0) sb.append('\n');
            sb.append(dist[a] + dist[b] - 2 * dist[m]);
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), q = sc.nextInt();
        int[][] edges = new int[n - 1][3];
        for (int i = 0; i < n - 1; i++) for (int j = 0; j < 3; j++) edges[i][j] = sc.nextInt();
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) { queries[i][0] = sc.nextInt(); queries[i][1] = sc.nextInt(); }
        System.out.println(solve(n, edges, queries));
    }
}

