    static long solve(int[] a) {
        final int BITS = 31;
        long[] basis = new long[BITS];
        for (int x : a) {
            long cur = x;
            for (int b = BITS - 1; b >= 0; b--) {
                if (((cur >> b) & 1L) == 0L) continue;
                if (basis[b] == 0) { basis[b] = cur; break; }
                cur ^= basis[b];
