    basis = [0] * BITS
    for x in a:
        cur = x
        for b in range(BITS - 1, -1, -1):
            if not (cur >> b) & 1:
                continue
            if basis[b] == 0:
                basis[b] = cur
                break
            cur ^= basis[b]
    for b in range(BITS):
        if basis[b] == 0:
            continue
        for h in range(b + 1, BITS):
            if basis[h] and (basis[h] >> b) & 1:
                basis[h] ^= basis[b]
    vals = sorted(v for v in basis if v)
    r = len(vals)
    if k > (1 << r):
        return -1
    idx = k - 1
    res = 0
    for i in range(r):
        if (idx >> i) & 1:
            res ^= vals[i]
    return res

