min-cut-capacity.java:
import java.util.*;

public class Main {
    static long solve(int n, int[][] edges) {
        int m = edges.length;
        int[] to = new int[2 * m];
        long[] cap = new long[2 * m];
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        int ec = 0;
        for (int[] e : edges) {
            g.get(e[0]).add(ec); to[ec] = e[1]; cap[ec] = e[2]; ec++;
            g.get(e[1]).add(ec); to[ec] = e[0]; cap[ec] = 0;    ec++;
        }
        int s = 0, t = n - 1;
        long flow = 0;
        int[] par = new int[n];
        int[] queue = new int[n];
        while (true) {
            Arrays.fill(par, -1);
            par[s] = -2;
            int head = 0, tail = 0;
            queue[tail++] = s;
            while (head < tail && par[t] == -1) {
                int u = queue[head++];
                for (int eid : g.get(u)) {
                    int v = to[eid];
                    if (cap[eid] > 0 && par[v] == -1) { par[v] = eid; queue[tail++] = v; }
                }
            }
            if (par[t] == -1) return flow;
            long push = Long.MAX_VALUE;
            for (int v = t; v != s; ) {
                int eid = par[v];
                push = Math.min(push, cap[eid]);
                v = to[eid ^ 1];
            }
            for (int v = t; v != s; ) {
                int eid = par[v];
                cap[eid] -= push;
                cap[eid ^ 1] += push;
                v = to[eid ^ 1];
            }
            flow += push;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        int[][] edges = new int[m][3];
        for (int i = 0; i < m; i++) for (int j = 0; j < 3; j++) edges[i][j] = sc.nextInt();
        System.out.println(solve(n, edges));
    }
}

