import sys
import heapq
from bisect import bisect_left, bisect_right
from collections import Counter, defaultdict, deque

L = sys.stdin.read().split('\n')
n = int(L[0])
a = list(map(int, L[1].split()))[:n]
q = int(L[2])
ops = [L[3 + i].split() for i in range(q)]

def solve(a, ops):
    n = len(a)
    size = 1
    while size < n:
        size <<= 1
    total = [0] * (2 * size)
    lazy_val = [0] * (2 * size)
    lazy_on = [False] * (2 * size)
    for i in range(n):
        total[size + i] = a[i]
    for i in range(size - 1, 0, -1):
        total[i] = total[2 * i] + total[2 * i + 1]

    def apply_node(node, lo, hi, v):
        total[node] = v * (hi - lo + 1)
        lazy_val[node] = v
        lazy_on[node] = True

    def push(node, lo, hi):
        if not lazy_on[node]:
            return
        mid = (lo + hi) // 2
        apply_node(2 * node, lo, mid, lazy_val[node])
        apply_node(2 * node + 1, mid + 1, hi, lazy_val[node])
        lazy_on[node] = False

    def update(node, lo, hi, l, r, v):
        if r < lo or hi < l:
            return
        if l <= lo and hi <= r:
            apply_node(node, lo, hi, v)
            return
        push(node, lo, hi)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, l, r, v)
        update(2 * node + 1, mid + 1, hi, l, r, v)
        total[node] = total[2 * node] + total[2 * node + 1]

    def query(node, lo, hi, l, r):
        if r < lo or hi < l:
            return 0
        if l <= lo and hi <= r:
            return total[node]
        push(node, lo, hi)
        mid = (lo + hi) // 2
        return query(2 * node, lo, mid, l, r) + query(2 * node + 1, mid + 1, hi, l, r)

    out = []
    for op in ops:
        if not op:
            continue
        if op[0] == "assign":
            update(1, 0, size - 1, int(op[1]), int(op[2]), int(op[3]))
        else:
            out.append(str(query(1, 0, size - 1, int(op[1]), int(op[2]))))
    return "\n".join(out)

print(solve(a, ops))

