        for (int t : a) mn = Math.min(mn, t);
        long lo = 1, hi = mn * k;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (enough(a, mid, k)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }

