        long l = a / gcd(a, b) * b;
        long lo = 1, hi = N * Math.min(a, b);
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            long c = mid / a + mid / b - mid / l;
            if (c >= N) hi = mid; else lo = mid + 1;
        }
