import java.util.*;

public class Main {
    static int[] parent;

    static int find(int s) {
        while (parent[s] != s) { parent[s] = parent[parent[s]]; s = parent[s]; }
        return s;
    }

    static long solve(int[][] p) {
        int maxD = 0;
        for (int[] j : p) maxD = Math.max(maxD, j[0]);
        parent = new int[maxD + 1];
        for (int i = 0; i <= maxD; i++) parent[i] = i;
        int[][] jobs = p.clone();
        Arrays.sort(jobs, (x, y) -> Integer.compare(y[1], x[1]));
        long total = 0;
        for (int[] j : jobs) {
            int s = find(j[0]);
            if (s > 0) {
                total += j[1];
                parent[s] = s - 1;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] p = new int[n][2];
        for (int i = 0; i < n; i++) { p[i][0] = sc.nextInt(); p[i][1] = sc.nextInt(); }
