import java.util.*;

public class Main {
    static long solve(int[][] t) {
        int n = t.length;
        int[][] b = t.clone();
        Arrays.sort(b, (x, y) -> Integer.compare(x[1], y[1]));
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) ends[i] = b[i][1];
        long[] best = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            int s = b[i - 1][0];
            int lo = 0, hi = n;                 // first index with ends[idx] > s
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ends[mid] <= s) lo = mid + 1; else hi = mid;
            }
            best[i] = Math.max(best[i - 1], b[i - 1][2] + best[lo]);
        }
        return best[n];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] t = new int[n][3];
        for (int i = 0; i < n; i++) for (int j = 0; j < 3; j++) t[i][j] = sc.nextInt();
