d = sys.stdin.read().split()
r, c = int(d[0]), int(d[1])
g = [list(row) for row in d[2:2 + r]]
cmds = d[2 + r]

def solve(g, cmds):
    r, c = len(g), len(g[0])

    def roll(cells):
        free = 0
        for idx, (i, j) in enumerate(cells):
            if g[i][j] == "#":
                free = idx + 1
            elif g[i][j] == "O":
                g[i][j] = "."
                a, b = cells[free]
                g[a][b] = "O"
                free += 1

    for d in cmds:
        if d in "LR":
            for i in range(r):
                cells = [(i, j) for j in range(c)]
                roll(cells if d == "L" else cells[::-1])
        else:
            for j in range(c):
                cells = [(i, j) for i in range(r)]
                roll(cells if d == "U" else cells[::-1])
    return "\n".join("".join(row) for row in g)

print(solve(g, cmds))

