import java.util.*;

public class Main {
    static void roll(char[][] g, int[][] cells) {
        int free = 0;
        for (int idx = 0; idx < cells.length; idx++) {
            int i = cells[idx][0], j = cells[idx][1];
            if (g[i][j] == '#') free = idx + 1;
            else if (g[i][j] == 'O') {
                g[i][j] = '.';
                g[cells[free][0]][cells[free][1]] = 'O';
                free++;
            }
        }
    }

    static String solve(char[][] g, String cmds) {
        int r = g.length, c = g[0].length;
        for (char d : cmds.toCharArray()) {
            if (d == 'L' || d == 'R') {
                for (int i = 0; i < r; i++) {
                    int[][] cells = new int[c][];
                    for (int j = 0; j < c; j++) cells[j] = new int[]{i, d == 'L' ? j : c - 1 - j};
                    roll(g, cells);
                }
            } else {
                for (int j = 0; j < c; j++) {
                    int[][] cells = new int[r][];
                    for (int i = 0; i < r; i++) cells[i] = new int[]{d == 'U' ? i : r - 1 - i, j};
                    roll(g, cells);
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < r; i++) {
            if (i > 0) sb.append('\n');
            sb.append(g[i]);
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        char[][] g = new char[r][];
        for (int i = 0; i < r; i++) g[i] = sc.next().toCharArray();
        String cmds = sc.next();
        System.out.println(solve(g, cmds));
    }
}

